<?php $rows=chr_rows($pdo,'shift_defaults');$edit=isset($_GET['edit'])?chr_record($pdo,'shift_defaults',(int)$_GET['edit']):null;$v=$edit?array_merge($edit['values'],['title'=>$edit['title']]):['from'=>date('Y-m-d')];if($error)$v=array_merge($v,$_POST);if(can($pdo,$user,'shifts.manage')):?><section class="card"><h2><?=$edit?'Edit assignment':'Assign a default shift'?></h2><form method="post" class="form-grid core-form"><?php ftoken();chr_hidden('action','att_default');chr_hidden('id',$edit['id']??0);chr_hidden('version',$edit['version']??0);field('title','Assignment name',$v,'text',true);choose('scope','Applies to',$v,['Company','Department']);chr_select('department_id','Department (department scope only)',$v['department_id']??'', [''=>'None']+$departmentOptions);chr_select('shift_id','Shift',$v['shift_id']??'', [''=>'Choose shift']+$shiftOptions);field('from','Effective from',$v,'date',true);field('to','Effective to (optional)',$v,'date');field('reason','Reason',$v,'text',true,2000);chr_checkbox('active','Active',!$edit||$edit['status']==='Active');?><div class="full"><button class="button primary">Save assignment</button> <a class="button" href="?page=roster">Individual overrides</a></div></form></section><?php endif;?>
<section class="card"><h2>Assignment history</h2><p>Individual assignment takes priority over department, then company. Set an end date before replacing a default. Repeat the department assignment for each department that uses the shift.</p><div class="table-scroll"><table class="directory"><thead><tr><th>Assignment</th><th>Scope</th><th>Shift</th><th>Effective dates</th><th>Assigned by / created</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$d=$r['values'];$q=$pdo->prepare('SELECT name FROM users WHERE id=?');$q->execute([$r['created_by']]);?><tr><td><?=h($r['title'])?></td><td><?=h($d['scope'])?><small><?=h($departmentOptions[$d['department_id']??0]??'All employees')?></small></td><td><?=h($shiftOptions[$d['shift_id']]??'Unavailable')?></td><td><?=h($d['from'])?> → <?=h($d['to']?:'Ongoing')?></td><td><?=h($q->fetchColumn())?><small><?=h($r['created_at'])?></small></td><td><?=h($r['status'])?></td><td><?php if(can($pdo,$user,'shifts.manage')):?><a class="button" href="?page=shift_defaults&edit=<?=(int)$r['id']?>">Edit</a><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7">No department or company defaults. Existing individual assignments still apply.</td></tr><?php endif;?></tbody></table></div></section>
